// Accept input from Manual (one or more items) or Webhook (single body).
// Ensures creatorId, creatorEmail, csvData, reportType on every item.
const items = $input.all();
const out = [];
for (const item of items) {
  const b = item.json.body || item.json;
  const csvData = b.csvData || b.csv_data || '';
  if (!csvData) {
    out.push({ json: { creatorId: b.creatorId || b.creator_id || 'unknown', creatorEmail: b.creatorEmail || b.creator_email || '', csvData: '', reportType: b.reportType || 'shopmy_export', _skip: true } });
    continue;
  }
  out.push({
    json: {
      creatorId: b.creatorId || b.creator_id || 'unknown',
      creatorEmail: b.creatorEmail || b.creator_email || '',
      csvData,
      reportType: b.reportType || b.report_type || 'shopmy_export'
    }
  });
}
return out.length ? out : [{ json: { creatorId: 'unknown', creatorEmail: '', csvData: '', reportType: 'shopmy_export', _skip: true } }];

// Parse CSV and add CreatorId, CreatorEmail, ReportType, ImportDate to every row.
const items = $input.all();
const records = [];
for (const item of items) {
  const { creatorId, creatorEmail, csvData, reportType, _skip } = item.json;
  if (_skip || !csvData) continue;
  const lines = csvData.trim().split('\n');
  const headers = lines[0].split(',').map(h => h.trim().replace(/^"|"$/g, ''));
  for (let i = 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    let current = '';
    let inQuotes = false;
    const values = [];
    for (const char of lines[i]) {
      if (char === '"') inQuotes = !inQuotes;
      else if (char === ',' && !inQuotes) { values.push(current.trim()); current = ''; }
      else current += char;
    }
    values.push(current.trim());
    const record = { ReportType: reportType || 'shopmy_export', ImportDate: new Date().toISOString(), CreatorId: creatorId, CreatorEmail: creatorEmail };
    headers.forEach((h, idx) => { if (values[idx] !== undefined) record[h] = values[idx].replace(/^"|"$/g, ''); });
    records.push({ json: record });
  }
}
return records.length > 0 ? records : [{ json: { error: 'No records parsed', success: false } }];

// Map each ShopMy row to canonical schema (CREATOR-EARNINGS-CANONICAL-SCHEMA.md §6).
const items = $input.all();
const earningsKeys = ['Commission','Commissions Earned','Order Total','Amount Earned','Amount'];
const dateKeys = ['Transaction Date','Completion Date','Payment Date','Created On','Created On'];
const out = [];
for (const item of items) {
  const row = item.json;
  if (row.error) continue;
  const creator_id = row.CreatorId || row.creatorId || 'unknown';
  let normalized_earnings = null;
  let raw_type = 'commission';
  for (const key of earningsKeys) {
    const v = row[key];
    if (v !== undefined && v !== null && v !== '') {
      const num = typeof v === 'number' ? v : parseFloat(String(v).replace(/[^0-9.-]/g, ''));
      if (!isNaN(num)) { normalized_earnings = num; raw_type = key.toLowerCase().replace(/\s+/g, '_'); break; }
    }
  }
  let period_start = null;
  let period_end = null;
  for (const key of dateKeys) {
    const v = row[key];
    if (v && typeof v === 'string') {
      const d = v.trim().slice(0, 10);
      if (/^\d{4}-\d{2}-\d{2}$/.test(d) || /^\d{1,2}\/\d{1,2}\/\d{2,4}$/.test(v)) {
        if (!period_start) period_start = d;
        period_end = d;
      }
    }
  }
  const recorded_at = new Date().toISOString();
  if (!period_start) period_start = recorded_at.slice(0, 10);
  if (!period_end) period_end = period_start;
  out.push({
    json: {
      creator_id,
      source_platform: 'shopmy',
      period_start,
      period_end,
      normalized_earnings: normalized_earnings ?? 0,
      currency: 'USD',
      raw_type,
      raw_payload: row,
      recorded_at
    }
  });
}
return out.length ? out : [];
